class entity;

class SoundScriptManager {
public:
	enum EventType { SS_FE_LEFTRIGHT = 26 };
	static SoundScriptManager *inst();
	void playEvent(EventType event, entity *ent = 0, float delay = 0.0f);
};

extern SoundScriptManager *sound_script_manager;
inline SoundScriptManager *SoundScriptManager::inst() { return sound_script_manager; }

class GraphicalMenuSystem {
	char pad[0xd4];
public:
	bool multiplayer;
	bool multi_1;
};

class game {
	char pad[0x258];
	int surferIdx[2];
	int personality[2];
public:
	int GetSurferIdx(int hero_num) const { return surferIdx[hero_num]; }
	bool GetUsingPersonalitySuit(int hero_num) const { return personality[hero_num]; }
};

class PanelQuad {
	char pad[0x194];
public:
	virtual ~PanelQuad();
	virtual void Init();
	virtual void TurnOn(bool enabled);
};

class BoardFrontEnd {
	char pad[0x164];
	GraphicalMenuSystem *sys;
	int current_board_index;
	char pad2[0x1c0 - 0x16c];
	PanelQuad *arrows[2][2];
	char pad3[0x268 - 0x1d0];
	int arrow_counter;
	int arrow_num;
public:
	void OnLeft(int c);
	bool IsLevelBoardUnlocked(int location);
	void OnHighlightBoard();
};

extern game *g_game_ptr;
extern int NumBoards[];

__asm__(".equ sound_script_manager, 0x0046B4A0");
__asm__(".equ g_game_ptr, 0x0045AC64");
__asm__(".equ NumBoards, 0x003FE2C0");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");
__asm__(".equ IsLevelBoardUnlocked__13BoardFrontEndi, 0x001B7250");
__asm__(".equ OnHighlightBoard__13BoardFrontEnd, 0x001B6208");

#define MAX_BOARDS 9
#define MAP_LOC_LAST 17
#define PERSONALITY_BOARD 0
#define arrow_timer 3
#define SS_FE_LEFTRIGHT SoundScriptManager::SS_FE_LEFTRIGHT

void BoardFrontEnd::OnLeft(int c)
{
	bool oneBoard=false;
	int maxBoards = MAX_BOARDS + MAP_LOC_LAST;

	SoundScriptManager::inst()->playEvent(SS_FE_LEFTRIGHT);		
	if (sys->multiplayer)
	{
		if ((sys->multi_1) && (g_game_ptr->GetUsingPersonalitySuit(0) || (NumBoards[g_game_ptr->GetSurferIdx(0)] == 1)))
			oneBoard = true;	
		else if ((!sys->multi_1) && (g_game_ptr->GetUsingPersonalitySuit(1) || (NumBoards[g_game_ptr->GetSurferIdx(1)] == 1)))
			oneBoard = true;
	}
	else
		oneBoard = g_game_ptr->GetUsingPersonalitySuit(0) || (NumBoards[g_game_ptr->GetSurferIdx(0)] == 1);



	if (oneBoard)
	{
		if (current_board_index == MAX_BOARDS)
			current_board_index = PERSONALITY_BOARD;
		else
			current_board_index--;
	}
	else if (current_board_index > 0)
		current_board_index--;
	else 
		current_board_index = maxBoards -1;

	if (current_board_index < 0)
		current_board_index = maxBoards - 1;


	if (current_board_index >= MAX_BOARDS)
	{
		while (!IsLevelBoardUnlocked( current_board_index - MAX_BOARDS ) && current_board_index >= MAX_BOARDS)
		{
			if (current_board_index > MAX_BOARDS)
				current_board_index--;
			else if (oneBoard)
			{
				current_board_index = PERSONALITY_BOARD;
			}
			else
				current_board_index--;
		}
	}



	arrows[0][1]->TurnOn(true);
	arrows[0][0]->TurnOn(false);
	arrow_num = 0;
	arrow_counter = arrow_timer;

	OnHighlightBoard();
}
